<p class="tm-lb">Size</p><div class="tm-chips" id="bt-s" role="group" aria-label="Size"><button type="button" data-v="0">Small</button><button type="button" class="on" data-v="1">Medium</button><button type="button" data-v="2">Large</button></div>
<p class="tm-lb">Wrapper</p><div class="tm-chips" id="bt-w" role="group" aria-label="Wrapper"><button type="button" class="on" data-v="0">Corn husks</button><button type="button" data-v="1">Banana leaves</button></div></div>
<div class="tm-bt-r"><div class="tm-total" aria-live="polite"><p class="tm-scr">make</p><b id="bt-n">36</b><span>tamales</span><div class="tm-row" id="bt-viz" aria-hidden="true"></div></div><ul class="tm-list" id="bt-l"></ul><p class="tm-p tm-note" id="bt-note"></p><figure class="tm-bt-i"><img src="https://images.unsplash.com/photo-1537734796389-e1fc293cf856?auto=format&fit=crop&w=520&h=260&q=75" alt="hands holding a piece of dough" width="520" height="260" loading="lazy"></figure></div></div></section>

<section class="tm-s tm-pr" id="pair"><div class="tm-w"><div class="tm-sh"><p class="tm-tag tm-tag-2">Herramienta 2</p><h2 class="rv">Filling &amp; salsa matcher</h2><p class="tm-p">Choose a filling and we suggest the salsa, the wrapper and the sides that suit it best, with a note on how to season the masa.</p></div>
